CREATE TABLE "books" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"title" text NOT NULL,"author" text NOT NULL,"description" text,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "book_editions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"book_id" uuid NOT NULL,"isbn" text,"publisher" text,"created_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "book_editions_isbn_unique" UNIQUE("isbn"));
CREATE TABLE "products" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"book_edition_id" uuid,"name" text NOT NULL,"description" text,"cover_url" text,"status" text DEFAULT 'DRAFT' NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "products_status_check" CHECK ("status" in ('DRAFT','ACTIVE','INACTIVE')));
CREATE TABLE "skus" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"product_id" uuid NOT NULL,"code" text NOT NULL,"name" text NOT NULL,"price_minor" integer NOT NULL,"status" text DEFAULT 'ACTIVE' NOT NULL,"available_for_sale" boolean DEFAULT true NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "skus_code_unique" UNIQUE("code"),CONSTRAINT "skus_price_nonnegative" CHECK ("price_minor" >= 0),CONSTRAINT "skus_status_check" CHECK ("status" in ('ACTIVE','INACTIVE')));
CREATE TABLE "product_media" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"product_id" uuid NOT NULL,"url" text NOT NULL,"display_order" integer DEFAULT 0 NOT NULL,CONSTRAINT "product_media_order_nonnegative" CHECK ("display_order" >= 0));
CREATE TABLE "carts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"consumer_user_id" uuid NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "carts_consumer_unique" UNIQUE("consumer_user_id"));
CREATE TABLE "cart_items" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"cart_id" uuid NOT NULL,"sku_id" uuid NOT NULL,"quantity" integer NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "cart_items_cart_sku_unique" UNIQUE("cart_id","sku_id"),CONSTRAINT "cart_items_quantity_check" CHECK ("quantity" between 1 and 99));
CREATE TABLE "user_addresses" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"consumer_user_id" uuid NOT NULL,"recipient_name" text NOT NULL,"phone" text NOT NULL,"region" text NOT NULL,"city" text NOT NULL,"district" text NOT NULL,"address_line" text NOT NULL,"postal_code" text,"is_default" boolean DEFAULT false NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "orders" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"consumer_user_id" uuid NOT NULL,"order_number" text NOT NULL,"status" text DEFAULT 'UNPAID' NOT NULL,"subtotal_minor" integer NOT NULL,"total_minor" integer NOT NULL,"address_snapshot" jsonb NOT NULL,"client_request_id" text NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,"cancelled_at" timestamptz,CONSTRAINT "orders_number_unique" UNIQUE("order_number"),CONSTRAINT "orders_consumer_request_unique" UNIQUE("consumer_user_id","client_request_id"),CONSTRAINT "orders_status_check" CHECK ("status" in ('UNPAID','PAID','PROCESSING','PICKUP_READY','DELIVERING','COMPLETED','CANCELLED','REFUNDING','REFUNDED')),CONSTRAINT "orders_amount_nonnegative" CHECK ("subtotal_minor" >= 0 and "total_minor" >= 0));
CREATE TABLE "order_items" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"order_id" uuid NOT NULL,"sku_id" uuid NOT NULL,"product_name_snapshot" text NOT NULL,"sku_name_snapshot" text NOT NULL,"sku_code_snapshot" text NOT NULL,"unit_price_minor" integer NOT NULL,"quantity" integer NOT NULL,"line_total_minor" integer NOT NULL,CONSTRAINT "order_items_quantity_check" CHECK ("quantity" between 1 and 99),CONSTRAINT "order_items_amount_nonnegative" CHECK ("unit_price_minor" >= 0 and "line_total_minor" >= 0));
ALTER TABLE "book_editions" ADD CONSTRAINT "book_editions_book_id_books_id_fk" FOREIGN KEY ("book_id") REFERENCES "books"("id") ON DELETE cascade;
ALTER TABLE "products" ADD CONSTRAINT "products_book_edition_id_book_editions_id_fk" FOREIGN KEY ("book_edition_id") REFERENCES "book_editions"("id") ON DELETE restrict;
ALTER TABLE "skus" ADD CONSTRAINT "skus_product_id_products_id_fk" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE cascade;
ALTER TABLE "product_media" ADD CONSTRAINT "product_media_product_id_products_id_fk" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE cascade;
ALTER TABLE "carts" ADD CONSTRAINT "carts_consumer_user_id_consumer_users_id_fk" FOREIGN KEY ("consumer_user_id") REFERENCES "consumer_users"("id") ON DELETE cascade;
ALTER TABLE "cart_items" ADD CONSTRAINT "cart_items_cart_id_carts_id_fk" FOREIGN KEY ("cart_id") REFERENCES "carts"("id") ON DELETE cascade;
ALTER TABLE "cart_items" ADD CONSTRAINT "cart_items_sku_id_skus_id_fk" FOREIGN KEY ("sku_id") REFERENCES "skus"("id") ON DELETE restrict;
ALTER TABLE "user_addresses" ADD CONSTRAINT "user_addresses_consumer_user_id_consumer_users_id_fk" FOREIGN KEY ("consumer_user_id") REFERENCES "consumer_users"("id") ON DELETE cascade;
ALTER TABLE "orders" ADD CONSTRAINT "orders_consumer_user_id_consumer_users_id_fk" FOREIGN KEY ("consumer_user_id") REFERENCES "consumer_users"("id") ON DELETE restrict;
ALTER TABLE "order_items" ADD CONSTRAINT "order_items_order_id_orders_id_fk" FOREIGN KEY ("order_id") REFERENCES "orders"("id") ON DELETE cascade;
ALTER TABLE "order_items" ADD CONSTRAINT "order_items_sku_id_skus_id_fk" FOREIGN KEY ("sku_id") REFERENCES "skus"("id") ON DELETE restrict;
CREATE INDEX "products_status_name_idx" ON "products" ("status","name");
CREATE INDEX "skus_product_idx" ON "skus" ("product_id");
CREATE INDEX "product_media_product_order_idx" ON "product_media" ("product_id","display_order");
CREATE UNIQUE INDEX "user_addresses_default_unique" ON "user_addresses" ("consumer_user_id") WHERE "is_default" = true;
CREATE INDEX "user_addresses_consumer_idx" ON "user_addresses" ("consumer_user_id");
CREATE INDEX "orders_consumer_created_idx" ON "orders" ("consumer_user_id","created_at");
CREATE INDEX "order_items_order_idx" ON "order_items" ("order_id");
INSERT INTO "permissions" ("key","display_name","description") VALUES ('catalog.manage','Manage catalog','Manage M5 products and SKUs') ON CONFLICT ("key") DO NOTHING;
